var options = new ExecutionDataflowBlockOptions
{
    MaxDegreeOfParallelism = Environment.ProcessorCount,
    BoundedCapacity = 1024            // back-pressure: Post() returns false when full
};
var performer = new ActionBlock<Message>(async msg => await HandleAsync(msg), options);
foreach (var msg in batch)
    await performer.SendAsync(msg);   // dispatch = post, exactly one delegate invocation
performer.Complete();
await performer.Completion;           // drain before shutdown
